 507	// checkTargetHas fails unless the target has every seeded commit the
 508	// translated objects build on. The source's notes name the SHA1 commits
 509	// convert-sha256 started from, which only the original repository holds.
 510	// Pushing to another repository would fail on missing objects after the
 511	// whole pack was sent.
 512	//
 513	// It asks the target's upload-pack for those commits while claiming to have
 514	// them, so a target that holds them sends an empty pack. upload-pack refuses
 515	// a commit it does not have, or one no ref reaches.
 516	func (s *syncSession) checkTargetHas(ctx context.Context, seeds []translate.Pair) error {
 517		tips := make(map[plumbing.Hash]struct{}, len(s.target.refMap))
 518		for _, h := range s.target.refMap {
 519			tips[h] = struct{}{}
 520		}
 521		desired := make(map[plumbing.ReferenceName]gitproto.DesiredRef)
 522		haves := make(map[plumbing.ReferenceName]plumbing.Hash)
 523		var example translate.Pair
 524		for _, p := range seeds {
 525			if _, ok := tips[p.Target]; ok {
 526				continue
 527			}
 528			name := plumbing.ReferenceName("refs/git-sync/check/" + p.Target.String())
 529			desired[name] = gitproto.DesiredRef{SourceRef: name, TargetRef: name, SourceHash: p.Target}
 530			haves[name] = p.Target
 531			example = p
 532		}
 533		if len(desired) == 0 {
 534			return nil
 535		}
 536		_, service, err := gitproto.ListSourceRefs(ctx, s.target.conn, s.cfg.ProtocolMode, []string{targetOriginNotesRef.String()})
 537		if err != nil {
 538			return fmt.Errorf("list target refs: %w", err)
 539		}
 540		store := memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA1))
 541		if err := service.FetchToStore(ctx, store, s.target.conn, desired, haves); err != nil &&
 542			!errors.Is(err, git.NoErrAlreadyUpToDate) {
 543			return fmt.Errorf("the target does not have %d SHA1 commit(s) the translated history builds on, such as %s (SHA256 %s). "+
 544				"Sync to the repository the source was converted from: %w", len(desired), example.Target, example.Source, err)
 545		}
 546		return nil
 547	}
