    22	// ReadHashNotes reads a notes ref whose notes each hold one object hash, as
    23	// convert-sha256's refs/notes/sha1-origin does. It returns the annotated
    24	// object to noted hash mapping and the tree entries it came from, so a
    25	// caller can extend the notes without reading every blob again.
    26	//
    27	// tip is the commit the notes ref points at, or the tree, which git also
    28	// accepts. Both flat trees and fanout trees (annotated hashes split across
    29	// nested directories) are read.
    30	func ReadHashNotes(store storer.EncodedObjectStorer, tip plumbing.Hash) (map[plumbing.Hash]plumbing.Hash, []NoteEntry, error) {
    31		obj, err := store.EncodedObject(plumbing.AnyObject, tip)
    32		if err != nil {
    33			return nil, nil, fmt.Errorf("load notes %s: %w", tip, err)
    34		}
    35		treeHash := tip
    36		if obj.Type() == plumbing.CommitObject {
    37			c, err := object.DecodeCommit(store, obj)
    38			if err != nil {
    39				return nil, nil, fmt.Errorf("decode notes commit %s: %w", tip, err)
    40			}
    41			treeHash = c.TreeHash
    42		} else if obj.Type() != plumbing.TreeObject {
    43			return nil, nil, fmt.Errorf("notes %s is a %s, not a commit or tree", tip, obj.Type())
    44		}
    45		tree, err := object.GetTree(store, treeHash)
    46		if err != nil {
    47			return nil, nil, fmt.Errorf("load notes tree %s: %w", treeHash, err)
    48		}
    49		values := make(map[plumbing.Hash]plumbing.Hash)
    50		var entries []NoteEntry
    51		if err := readNotesTree(store, tree, "", values, &entries); err != nil {
    52			return nil, nil, err
    53		}
    54		return values, entries, nil
    55	}
