    57	func readNotesTree(store storer.EncodedObjectStorer, tree *object.Tree, prefix string, values map[plumbing.Hash]plumbing.Hash, entries *[]NoteEntry) error {
    58		for _, e := range tree.Entries {
    59			name := prefix + e.Name
    60			if e.Mode == filemode.Dir {
    61				sub, err := object.GetTree(store, e.Hash)
    62				if err != nil {
    63					return fmt.Errorf("load notes subtree %s: %w", name, err)
    64				}
    65				if err := readNotesTree(store, sub, name, values, entries); err != nil {
    66					return err
    67				}
    68				continue
    69			}
    70			annotated, ok := plumbing.FromHex(name)
    71			if !ok {
    72				// Not a note: git notes trees may carry other files.
    73				continue
    74			}
    75			blob, err := store.EncodedObject(plumbing.BlobObject, e.Hash)
    76			if err != nil {
    77				return fmt.Errorf("load note for %s: %w", name, err)
    78			}
    79			content, err := readAll(blob)
    80			if err != nil {
    81				return fmt.Errorf("read note for %s: %w", name, err)
    82			}
    83			fields := bytes.Fields(content)
    84			if len(fields) == 0 {
    85				return fmt.Errorf("note for %s is empty", name)
    86			}
    87			noted, ok := plumbing.FromHex(string(fields[0]))
    88			if !ok {
    89				return fmt.Errorf("note for %s does not hold an object hash", name)
    90			}
    91			values[annotated] = noted
    92			*entries = append(*entries, NoteEntry{Object: annotated, Blob: e.Hash})
    93		}
    94		return nil
    95	}
