    97	// WriteHashNotes writes a notes commit holding existing plus one note per
    98	// pair in add, keyed by Pair.Target and holding Pair.Source. The tree is
    99	// flat. parent is the previous notes commit, or zero for the first one. It
   100	// returns the new commit and every object it wrote, which are the objects a
   101	// push of the notes ref must send.
   102	func WriteHashNotes(store storer.EncodedObjectStorer, parent plumbing.Hash, existing []NoteEntry, add []Pair, sig object.Signature, message string) (plumbing.Hash, []plumbing.Hash, error) {
   103		if len(add) == 0 {
   104			return plumbing.ZeroHash, nil, errors.New("no notes to add")
   105		}
   106		byName := make(map[string]plumbing.Hash, len(existing)+len(add))
   107		for _, e := range existing {
   108			byName[e.Object.String()] = e.Blob
   109		}
   110		written := make([]plumbing.Hash, 0, len(add)+2)
   111		for _, p := range add {
   112			blob, err := writeObject(store, plumbing.BlobObject, []byte(p.Source.String()+"\n"))
   113			if err != nil {
   114				return plumbing.ZeroHash, nil, fmt.Errorf("store note for %s: %w", p.Target, err)
   115			}
   116			byName[p.Target.String()] = blob
   117			written = append(written, blob)
   118		}
   119	
   120		tree := &object.Tree{Entries: make([]object.TreeEntry, 0, len(byName))}
   121		for name, blob := range byName {
   122			tree.Entries = append(tree.Entries, object.TreeEntry{Name: name, Mode: filemode.Regular, Hash: blob})
   123		}
   124		sort.Slice(tree.Entries, func(i, j int) bool { return tree.Entries[i].Name < tree.Entries[j].Name })
   125		treeHash, err := encodeObject(store, tree.Encode)
   126		if err != nil {
   127			return plumbing.ZeroHash, nil, fmt.Errorf("store notes tree: %w", err)
   128		}
   129		written = append(written, treeHash)
   130	
   131		commit := &object.Commit{Author: sig, Committer: sig, Message: message, TreeHash: treeHash}
   132		if !parent.IsZero() {
   133			commit.ParentHashes = []plumbing.Hash{parent}
   134		}
   135		commitHash, err := encodeObject(store, commit.Encode)
   136		if err != nil {
   137			return plumbing.ZeroHash, nil, fmt.Errorf("store notes commit: %w", err)
   138		}
   139		written = append(written, commitHash)
   140		return commitHash, written, nil
   141	}
   142	
   143	func encodeObject(store storer.EncodedObjectStorer, encode func(plumbing.EncodedObject) error) (plumbing.Hash, error) {
   144		obj := store.NewEncodedObject()
   145		if err := encode(obj); err != nil {
   146			return plumbing.ZeroHash, err
   147		}
   148		h, err := store.SetEncodedObject(obj)
   149		if err != nil {
   150			return plumbing.ZeroHash, fmt.Errorf("set object: %w", err)
   151		}
   152		return h, nil
   153	}
