			top := append(entry("100011", "a", blob), entry("040000", "d", inner)...)
			tree := writeObj(t, origin, "tree", top, true)
			base := commitTree(t, origin, "1700000000 +0000", tree, "", "base")
			gitAt(t, origin, "", "update-ref", "refs/heads/main", base)
			gitAt(t, root, "", "clone", "--bare", origin, oracle)

			srv := newReadOnlyOriginServer(t, gitBin, root, "origin.git", token)
			defer srv.Close()

			if _, err := Run(context.Background(), Request{
				SourceURL:       srv.URL + "/origin.git",
				TargetDir:       canonical,
				RewriteMessages: rewrite,
				Out:             io.Discard,
			}); err != nil {
				t.Fatalf("convert-sha256: %v", err)
			}
			gitAt(t, canonical, "", "config", "http.receivepack", "true")
			raw := mustGitOutput(t, canonical, "cat-file", "-p", "main^{tree}")
			if !strings.Contains(raw, "100011 blob") {
				t.Fatalf("converted tree lost the odd mode:\n%s", raw)
			}
			t.Logf("canonical tree:\n%s", raw)

			// Post-cutover empty commit that reuses the converted tree.
			cTree := strings.TrimSpace(mustGitOutput(t, canonical, "rev-parse", "main^{tree}"))
			cMain := strings.TrimSpace(mustGitOutput(t, canonical, "rev-parse", "main"))
			next := commitTree(t, canonical, "1700001000 +0000", cTree, cMain, "empty")
			gitAt(t, canonical, "", "update-ref", "refs/heads/main", next)

			want := commitTree(t, oracle, "1700001000 +0000", tree, base, "empty")

			client := gitsync.New(gitsync.Options{
